  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

#root {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.container {
  text-align: center;
  max-width: 600px;
  padding: 2rem;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);
  border: 1px solid rgba(255, 255, 255, 0.18);
}

h1 {
  font-size: 3rem;
  margin-bottom: 0.5rem;
  background: linear-gradient(45deg, #ffd700, #ffed4e);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  font-size: 1.2rem;
  margin-bottom: 2rem;
  opacity: 0.9;
}

.coin-container {
  position: relative;
  width: 150px;
  height: 150px;
  margin: 2rem auto;
}

.coin {
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: linear-gradient(45deg, #ffd700, #ffed4e);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  font-weight: bold;
  color: #333;
  box-shadow: 0 8px 16px rgba(255, 215, 0, 0.3);
  transition: transform 0.3s ease;
  cursor: pointer;
}

.coin:hover {
  transform: scale(1.05);
}

.coin.flipping {
  animation: flip 1s ease-in-out;
}

@keyframes flip {
  0% { transform: rotateY(0deg); }
  50% { transform: rotateY(90deg); }
  100% { transform: rotateY(0deg); }
}

.choice-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin: 2rem 0;
}

.choice-btn {
  padding: 1rem 2rem;
  font-size: 1.1rem;
  font-weight: bold;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  background: linear-gradient(45deg, #4facfe, #00f2fe);
  color: white;
  transition: all 0.3s ease;
  min-width: 120px;
}

.choice-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 16px rgba(79, 172, 254, 0.3);
}

.choice-btn.selected {
  background: linear-gradient(45deg, #43e97b, #38f9d7);
}

.play-btn {
  padding: 1rem 3rem;
  font-size: 1.3rem;
  font-weight: bold;
  border: none;
  border-radius: 15px;
  cursor: pointer;
  background: linear-gradient(45deg, #f093fb, #f5576c);
  color: white;
  transition: all 0.3s ease;
  margin: 1rem;
}

.play-btn:hover:not(:disabled) {
  transform: translateY(-3px);
  box-shadow: 0 12px 24px rgba(245, 87, 108, 0.4);
}

.play-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.result {
  font-size: 1.5rem;
  font-weight: bold;
  margin: 1rem 0;
  min-height: 2rem;
}

.result.win {
  color: #43e97b;
}

.result.lose {
  color: #f5576c;
}

.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 1rem;
  margin-top: 2rem;
}

.stat {
  background: rgba(255, 255, 255, 0.1);
  padding: 1rem;
  border-radius: 10px;
  text-align: center;
}

.stat-value {
  font-size: 2rem;
  font-weight: bold;
  color: #ffd700;
}

.stat-label {
  font-size: 0.9rem;
  opacity: 0.8;
  margin-top: 0.5rem;
}

.leaderboard {
  margin-top: 2rem;
  text-align: left;
}

.leaderboard h3 {
  text-align: center;
  margin-bottom: 1rem;
  color: #ffd700;
}

.leaderboard-entry {
  display: flex;
  justify-content: space-between;
  padding: 0.5rem 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.connect-wallet {
  background: linear-gradient(45deg, #667eea, #764ba2);
  border: 2px solid rgba(255, 255, 255, 0.3);
}

.loading {
  opacity: 0.7;
}"}

{"path": "src/App.jsx", "content": "import { useState, useEffect } from 'react'
import { ethers } from 'ethers'

function App() {
  const [account, setAccount] = useState('')
  const [choice, setChoice] = useState('')
  const [result, setResult] = useState('')
  const [isFlipping, setIsFlipping] = useState(false)
  const [coinFace, setCoinFace] = useState('🪙')
  const [stats, setStats] = useState({
    points: 0,
    wins: 0,
    losses: 0,
    streak: 0
  })
  const [leaderboard, setLeaderboard] = useState([])
  const [isLoading, setIsLoading] = useState(false)

  // Connect wallet
  const connectWallet = async () => {
    if (typeof window.ethereum !== 'undefined') {
      try {
        await window.ethereum.request({ method: 'eth_requestAccounts' })
        const provider = new ethers.BrowserProvider(window.ethereum)
        const signer = await provider.getSigner()
        const address = await signer.getAddress()
        setAccount(address)
        loadPlayerStats(address)
      } catch (error) {
        console.error('Error connecting wallet:', error)
      }
    } else {
      alert('MetaMask is required to play this game!')
    }
  }

  // Load player stats from localStorage (in a real app, this would be from the blockchain)
  const loadPlayerStats = (address) => {
    const savedStats = localStorage.getItem(`coinflip_${address}`)
    if (savedStats) {
      setStats(JSON.parse(savedStats))
    }
  }

  // Save player stats
  const saveStats = (newStats) => {
    setStats(newStats)
    if (account) {
      localStorage.setItem(`coinflip_${account}`, JSON.stringify(newStats))
      updateLeaderboard(account, newStats.points)
    }
  }

  // Update leaderboard
  const updateLeaderboard = (address, points) => {
    const leaderboardData = JSON.parse(localStorage.getItem('coinflip_leaderboard') || '[]')
    const existingIndex = leaderboardData.findIndex(entry => entry.address === address)

    if (existingIndex !== -1) {
      leaderboardData[existingIndex].points = points
    } else {
      leaderboardData.push({
        address: address.slice(0, 6) + '...' + address.slice(-4),
        points
      })
    }

    leaderboardData.sort((a, b) => b.points - a.points)
    leaderboardData.splice(10) // Keep only top 10

    localStorage.setItem('coinflip_leaderboard', JSON.stringify(leaderboardData))
    setLeaderboard(leaderboardData)
  }

  // Load leaderboard on component mount
  useEffect(() => {
    const leaderboardData = JSON.parse(localStorage.getItem('coinflip_leaderboard') || '[]')
    setLeaderboard(leaderboardData)
  }, [])

  // Simulate coin flip with Pyth Entropy (for now, we'll use mock randomness)
  const flipCoin = async () => {
    if (!choice || !account) return

    setIsLoading(true)
    setIsFlipping(true)
    setResult('')

    // Simulate transaction delay
    await new Promise(resolve => setTimeout(resolve, 1000))

    // Mock random number (in real implementation, this would come from Pyth Entropy)
    const randomValue = Math.random()
    const actualResult = randomValue < 0.5 ? 'heads' : 'tails'
    const won = choice === actualResult

    // Update coin face
    setCoinFace(actualResult === 'heads' ? '🪙' : '⚫')

    // Update result
    setResult(won ? 'You Won!' : 'You Lost!')

    // Update stats
    const newStats = { ...stats }
    if (won) {
      newStats.points += 10
      newStats.wins += 1
      newStats.streak += 1
    } else {
      newStats.points += 1 // Consolation point
      newStats.losses += 1
      newStats.streak = 0
    }

    saveStats(newStats)

    setTimeout(() => {
      setIsFlipping(false)
      setIsLoading(false)
    }, 500)
  }

  const formatAddress = (address) => {
    return address ? `${address.slice(0, 6)}...${address.slice(-4)}` : ''
  }

  return (
    <div className="container">
      <h1>🪙 Coin Flip</h1>
      <p className="subtitle">Choose heads or tails and test your luck!</p>

      {!account ? (
        <button className="play-btn connect-wallet" onClick={connectWallet}>
          Connect Wallet to Play
        </button>
      ) : (
        <>
          <p>Connected: {formatAddress(account)}</p>

          <div className="coin-container">
            <div className={`coin ${isFlipping ? 'flipping' : ''}`}>
              {coinFace}
            </div>
          </div>

          <div className="choice-buttons">
            <button 
              className={`choice-btn ${choice === 'heads' ? 'selected' : ''}`}
              onClick={() => setChoice('heads')}
              disabled={isLoading}
            >
              Heads 🪙
            </button>
            <button 
              className={`choice-btn ${choice === 'tails' ? 'selected' : ''}`}
              onClick={() => setChoice('tails')}
              disabled={isLoading}
            >
              Tails ⚫
            </button>
          </div>

          <button 
            className={`play-btn ${isLoading ? 'loading' : ''}`}
            onClick={flipCoin}
            disabled={!choice || isLoading}
          >
            {isLoading ? 'Flipping...' : 'Flip Coin!'}
          </button>

          {result && (
            <div className={`result ${result.includes('Won') ? 'win' : 'lose'}`}>
              {result}
              <br />
              <small>
                {result.includes('Won') ? '+10 points!' : '+1 consolation point'}
              </small>
            </div>
          )}

          <div className="stats">
            <div className="stat">
              <div className="stat-value">{stats.points}</div>
              <div className="stat-label">Total Points</div>
            </div>
            <div className="stat">
              <div className="stat-value">{stats.wins}</div>
              <div className="stat-label">Wins</div>
            </div>
            <div className="stat">
              <div className="stat-value">{stats.losses}</div>
              <div className="stat-label">Losses</div>
            </div>
            <div className="stat">
              <div className="stat-value">{stats.streak}</div>
              <div className="stat-label">Win Streak</div>
            </div>
          </div>

          {leaderboard.length > 0 && (
            <div className="leaderboard">
              <h3>🏆 Leaderboard</h3>
              {leaderboard.map((entry, index) => (
                <div key={entry.address} className="leaderboard-entry">
                  <span>#{index + 1} {entry.address}</span>
                  <span>{entry.points} points</span>
                </div>
              ))}
            </div>
          )}
        </>
      )}
    </div>
  )
}

export default App"}

{"path": "contracts/CoinFlip.sol", "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@pythnetwork/entropy-sdk-solidity/IEntropy.sol";
import "@pythnetwork/entropy-sdk-solidity/IEntropyConsumer.sol";

contract CoinFlip is IEntropyConsumer {
    IEntropy private entropy;
    address private entropyProvider;

    struct Game {
        address player;
        bool choice; // true = heads, false = tails
        bool pending;
        uint64 sequenceNumber;
    }

    struct PlayerStats {
        uint256 points;
        uint256 wins;
        uint256 losses;
        uint256 streak;
    }

    mapping(uint64 => Game) public games;
    mapping(address => PlayerStats) public playerStats;
    mapping(address => bool) public hasPlayed;
    address[] public players;

    event GameStarted(address indexed player, uint64 sequenceNumber, bool choice);
    event GameResolved(address indexed player, bool choice, bool result, bool won, uint256 pointsEarned);

    constructor(address _entropy, address _entropyProvider) {
        entropy = IEntropy(_entropy);
        entropyProvider = _entropyProvider;
    }

    // Request randomness and start a game
    function playGame(bool _choice, bytes32 userCommitment) external payable {
        require(msg.value >= entropy.getFee(entropyProvider), "Insufficient fee");

        uint64 sequenceNumber = entropy.requestWithCallback{value: msg.value}(
            entropyProvider,
            userCommitment
        );

        games[sequenceNumber] = Game({
            player: msg.sender,
            choice: _choice,
            pending: true,
            sequenceNumber: sequenceNumber
        });

        // Add player to list if first time
        if (!hasPlayed[msg.sender]) {
            hasPlayed[msg.sender] = true;
            players.push(msg.sender);
        }

        emit GameStarted(msg.sender, sequenceNumber, _choice);
    }

    // Callback function called by Pyth Entropy
    function entropyCallback(
        uint64 sequenceNumber,
        address,
        bytes32 randomNumber
    ) internal override {
        Game storage game = games[sequenceNumber];
        require(game.pending, "Game already resolved");

        // Convert random number to coin flip result
        bool coinResult = (uint256(randomNumber) % 2) == 0; // true = heads, false = tails
        bool won = game.choice == coinResult;

        PlayerStats storage stats = playerStats[game.player];
        uint256 pointsEarned;

        if (won) {
            pointsEarned = 10;
            stats.wins++;
            stats.streak++;
        } else {
            pointsEarned = 1; // Consolation point
            stats.losses++;
            stats.streak = 0;
        }

        stats.points += pointsEarned;
        game.pending = false;

        emit GameResolved(game.player, game.choice, coinResult, won, pointsEarned);
    }

    // Get required fee for playing
    function getPlayFee() external view returns (uint256) {
        return entropy.getFee(entropyProvider);
    }

    // Get player stats
    function getPlayerStats(address player) external view returns (PlayerStats memory) {
        return playerStats[player];
    }

    // Get leaderboard (top 10 players by points)
    function getLeaderboard() external view returns (address[] memory topPlayers, uint256[] memory topPoints) {
        uint256 playerCount = players.length;
        if (playerCount == 0) {
            return (new address[](0), new uint256[](0));
        }

        // Simple bubble sort for small datasets
        address[] memory sortedPlayers = new address[](playerCount);
        uint256[] memory sortedPoints = new uint256[](playerCount);

        for (uint256 i = 0; i < playerCount; i++) {
            sortedPlayers[i] = players[i];
            sortedPoints[i] = playerStats[players[i]].points;
        }

        // Sort by points (descending)
        for (uint256 i = 0; i < playerCount - 1; i++) {
            for (uint256 j = 0; j < playerCount - i - 1; j++) {
                if (sortedPoints[j] < sortedPoints[j + 1]) {
                    // Swap points
                    uint256 tempPoints = sortedPoints[j];
                    sortedPoints[j] = sortedPoints[j + 1];
                    sortedPoints[j + 1] = tempPoints;

                    // Swap addresses
                    address tempAddr = sortedPlayers[j];
                    sortedPlayers[j] = sortedPlayers[j + 1];
                    sortedPlayers[j + 1] = tempAddr;
                }
            }
        }

        // Return top 10 or less
        uint256 returnCount = playerCount > 10 ? 10 : playerCount;
        address[] memory topPlayersResult = new address[](returnCount);
        uint256[] memory topPointsResult = new uint256[](returnCount);

        for (uint256 i = 0; i < returnCount; i++) {
            topPlayersResult[i] = sortedPlayers[i];
            topPointsResult[i] = sortedPoints[i];
        }

        return (topPlayersResult, topPointsResult);
    }

    // Get game info
    function getGame(uint64 sequenceNumber) external view returns (Game memory) {
        return games[sequenceNumber];
    }

    // Emergency withdraw function for contract owner
    function withdraw() external {
        require(msg.sender == address(this)); // Only contract itself
        payable(msg.sender).transfer(address(this).balance);
    }
}"}
